from scipy.optimize import least_squares

def cr(a,b):return a[0]*b[1]-a[1]*b[0]
def u(t):return np.array([np.cos(t),np.sin(t)])
def ix(P,d,Q,e):return P+cr(Q-P,e)/cr(d,e)*d

def calc(C,q):
 a,b,g=q; A=np.arctan2(C[1],C[0]);B=np.array([1.,0]);M=B/2;N=C/2
 K=ix(B,u(np.pi-a),M,u(g)); L=ix(B,u(np.pi-a-b),N,u(A-b))
 return K,L,[cr(K-C,u(A+np.pi-a-g)),cr(L-C,u(A+np.pi-a))]
for C in [np.array([.3,1.1]),np.array([.8,.7]),np.array([-.2,.9])]:
 for a in [.08,.15,.25]:
  def f(x):return calc(C,[a,*x])[2]
  for guess in ([.1,.1],[.3,.3],[.6,.2],[.2,.6]):
